const byte TRIG_PIN = 7;
const byte ECHO_PIN = 6;
const byte BUZZER_PIN = 8;
const byte LED_PIN = 13;

unsigned long lastMeasurement = 0;
unsigned long lastBeep = 0;
unsigned long beepInterval = 1000;
bool warningActive = false;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(TRIG_PIN, LOW);
  digitalWrite(BUZZER_PIN, LOW);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  unsigned long now = millis();

  // Allow at least 60 ms between ultrasonic measurements.
  if (now - lastMeasurement >= 60) {
    lastMeasurement = now;
    digitalWrite(TRIG_PIN, LOW);
    delayMicroseconds(2);
    digitalWrite(TRIG_PIN, HIGH);
    delayMicroseconds(10);
    digitalWrite(TRIG_PIN, LOW);

    unsigned long echoTime = pulseIn(ECHO_PIN, HIGH, 25000UL);
    float distanceCm = echoTime * 0.0343f / 2.0f;
    bool validEcho = echoTime != 0;
    bool wasActive = warningActive;
    warningActive = validEcho && distanceCm <= 100.0f;
    digitalWrite(LED_PIN, validEcho && distanceCm < 10.0f ? HIGH : LOW);

    if (warningActive) {
      long limitedDistance = (long)constrain(distanceCm, 2.0f, 100.0f);
      beepInterval = (unsigned long)map(limitedDistance, 2, 100, 80, 1000);
      if (!wasActive) {
        tone(BUZZER_PIN, 2200, 35);
        lastBeep = millis();
      }
    } else {
      noTone(BUZZER_PIN);
    }
  }

  now = millis();
  if (warningActive && now - lastBeep >= beepInterval) {
    lastBeep = now;
    tone(BUZZER_PIN, 2200, 35);
  }
}

